/// <summary>
/// PricingAttribute of table <c>CustTable</c> field PaymMode.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Customer, UPSPricingAttributeSourceLevel::Header)]
internal class UPSPricingAttributeCustTablePaymMode extends UPSPricingAttributeCustTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(CustTable, PaymMode);
}

public Set getAllowedValues()
{
    var         ret = new Set(Types::String);
    CustTable   custTable;

    while select PaymMode from custTable
        group by PaymMode
    {
        ret.add(custTable.PaymMode);
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(CustTable, PaymMode));
    qbr.value(queryValue(_value));
}
